    private static final Logger logger = Logger.getLogger(EventBuffer.class);
    private LoggingEvent[] eventBuffer = new LoggingEvent[MAX_BUFFER_SIZE];
    private int bufferSize = 0;

    public void put(LoggingEvent o) {
        if (bufferSize < MAX_BUFFER_SIZE) {
            eventBuffer[bufferSize++] = o;
        } else {
            logger.warn("Event buffer is full, dropping new event.");
        }
    }

    public void clear() {
        bufferSize = 0;
    }

    public LoggingEvent[] getEvents() {
        LoggingEvent[] events = new LoggingEvent[bufferSize];
        System.arraycopy(eventBuffer, 0, events, 0, bufferSize);
        return events;
    }
}

import java.util.ArrayList;
