public class UnescapeJava {
    public static String unescapeJava(String str) throws Exception {
        if (str == null) {
            return null;
        }

        // Replace escaped backslashes with a temporary marker
        str = str.replace("\\\\", "__TEMP_BACKSLASH__");

        // Replace escaped double quotes with a temporary marker
        str = str.replace("\\\"", "__TEMP_DOUBLE_QUOTE__");

        // Replace escaped single quotes with a temporary marker
        str = str.replace("\\'", "__TEMP_SINGLE_QUOTE__");

        // Replace escaped newlines with a temporary marker
        str = str.replace("\\n", "__TEMP_NEWLINE__");

        // Replace escaped tabs with a temporary marker
        str = str.replace("\\t", "__TEMP_TAB__");

        // Replace escaped form feeds with a temporary marker
        str = str.replace("\\f", "__TEMP_FORM_FEED__");

        // Replace escaped backslashes with the actual backslash
        str = str.replace("__TEMP_BACKSLASH__", "\\");

        // Replace escaped double quotes with the actual double quote
        str = str.replace("__TEMP_DOUBLE_QUOTE__", "\"");

        // Replace escaped single quotes with the actual single quote
        str = str.replace("__TEMP_SINGLE_QUOTE__", "'");

        // Replace escaped newlines with the actual newline character
        str = str.replace("__TEMP_NEWLINE__", "\n");

        // Replace escaped tabs with the actual tab character
        str = str.replace("__TEMP_TAB__", "\t");

        // Replace escaped form feeds with the actual form feed character
        str = str.replace("__TEMP_FORM_FEED__", "\f");

        return str;
    }

    public static void main(String[] args) {
        try {
            String input = "This is a test string with \\n newlines, \\t tabs, \\\" double quotes, \\' single quotes, and \\\\ backslashes.";
            String output = unescapeJava(input);
            System.out.println(output);
        } catch (Exception e) {
            e.printStackTrace();
        }
    }
}

