protected <V, E extends DefaultEdge> GraphPath<V, E> edgeSetToTour(Set<E> tour, Graph<V, E> graph) {
    if (tour.isEmpty()) {
        return null;
    }

    Iterator<E> iterator = tour.iterator();
    E firstEdge = iterator.next();
    V startVertex = firstEdge.getSource();
    V endVertex = firstEdge.getTarget();

    GraphPath<V, E> path = new DefaultGraphPath<>(graph, startVertex, endVertex, 0.0);

    while (iterator.hasNext()) {
        E edge = iterator.next();
        path = path.extend(edge);
    }

    return path;
}

