public class DoublyLinkedList<E> {
    private ListNodeImpl<E> head;
    private ListNodeImpl<E> tail;
    private int size;

    public boolean unlink(ListNodeImpl<E> node) {
        if (node == null) {
            throw new NoSuchElementException("Node cannot be null");
        }

        if (node.prev != null) {
            node.prev.next = node.next;
        } else {
            head = node.next;
        }

        if (node.next != null) {
            node.next.prev = node.prev;
        } else {
            tail = node.prev;
        }

        node.prev = null;
        node.next = null;
        size--;
        return true;
    }

    public static void main(String[] args) {
        DoublyLinkedList<Integer> list = new DoublyLinkedList<>();
        ListNodeImpl<Integer> node1 = new ListNodeImpl<>(1);
        ListNodeImpl<Integer> node2 = new ListNodeImpl<>(2);
        ListNodeImpl<Integer> node3 = new ListNodeImpl<>(3);

        list.head = node1;
        node1.next = node2;
        node2.prev = node1;
        node2.next = node3;
        node3.prev = node2;

        list.unlink(node2);

        // Check if the list is correctly unlinked
        System.out.println(list.head.value); // Should print 1
        System.out.println(list.head.next.value); // Should print 3
        System.out.println(list.tail.value); // Should print 3
    }
}

