private Pair<List<Integer>, Long> computeSuffixSum(List<Integer> bounds) {
    List<Integer> suffixSum = new ArrayList<>();
    long totalSum = 0;
    long currentSum = 0;

    for (int i = bounds.size() - 1; i >= 0; i--) {
        currentSum += bounds.get(i);
        suffixSum.add(0, (int) currentSum);
        totalSum += bounds.get(i);
    }

    return Pair.with(suffixSum, totalSum);
}

public static final <V> void reverse(V[] arr, int from, int to) {
    while (from < to) {
        V temp = arr[from];
        arr[from++] = arr[to];
        arr[to--] = temp;
    }
}

import java.util.Iterator;

public class DoublyLinkedList<E> {
    private static class ListNodeImpl<E> {
        E value;
        ListNodeImpl<E> prev;
        ListNodeImpl<E> next;

        ListNodeImpl(E value) {
            this.value = value;
            this.prev = null;
            this.next = null;
        }
    }

    private ListNodeImpl<E> head;
    private ListNodeImpl<E> tail;

    public void moveAllListNodes(DoublyLinkedList<E> list) {
        Iterator<ListNodeImpl<E>> iterator = list.iterator();
        while (iterator.hasNext()) {
            ListNodeImpl<E> node = iterator.next();
            iterator.remove();
            addListNode(node);
        }
    }

    public Iterator<ListNodeImpl<E>> iterator() {
        return new Iterator<ListNodeImpl<E>>() {
            private ListNodeImpl<E> current = head;

            @Override
            public boolean hasNext() {
                return current != null;
            }

            @Override
            public ListNodeImpl<E> next() {
                ListNodeImpl<E> node = current;
                current = current.next;
                return node;
            }

            @Override
            public void remove() {
                if (current == null) {
                    throw new IllegalStateException();
                }
                if (current.prev != null) {
                    current.prev.next = current.next;
                } else {
                    head = current.next;
                }
                if (current.next != null) {
                    current.next.prev = current.prev;
                } else {
                    tail = current.prev;
                }
                current = current.prev;
            }
        };
    }

    public void addListNode(ListNodeImpl<E> node) {
        if (tail == null) {
            head = tail = node;
        } else {
            tail.next = node;
            node.prev = tail;
            tail = node;
        }
    }
}

